/**
 * #1674 — the web's offline page (`public/offline-basic.html`) and its build.
 *
 * Both files are generated by `prebuild`, so a mistake here shows up only when
 * a signed-in web user is offline: a blank page (CSP hash mismatch), a page
 * that never comes back (probe trusts a redirect), or a page that leaks the
 * URL. The native `out/offline.html` shares the renderer and must not change.
 */
import { describe, it, expect } from 'vitest'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import {
  PROD_SERVER_URL,
  WEB_LOCALE_COOKIE,
  WEB_OFFLINE_PREF_KEY,
  WEB_PROBE_PATH,
  renderOfflinePage,
  renderWebOfflinePage,
} from '../scripts/build-native-offline-page.ts'
import { buildOfflineBasic, inlineScriptHashes, sha256Hex } from '../scripts/build-web-offline-basic.ts'
import { basicCacheName, renderBasicWorker } from '../scripts/sw-basic-worker.ts'
import { offlineBasicCsp, OFFLINE_BASIC_BUILD_ARTIFACT } from '../lib/offline/offlineBasicHeaders'
import { OFFLINE_PREF_KEY } from '../lib/offline/preference'
import { LOCALE_COOKIE, SUPPORTED_LOCALES } from '../lib/i18n/locales-meta'
import { SW_BASIC_MODE } from '../lib/offline/swBasicMode'
import { zhTW } from '../lib/i18n/locales/zh-TW'
import { zhCN } from '../lib/i18n/locales/zh-CN'
import { en } from '../lib/i18n/locales/en'
import { ja } from '../lib/i18n/locales/ja'

const repoRoot = resolve(__dirname, '..')
const hex = (s: string) => createHash('sha256').update(s, 'utf8').digest('hex')
const html = renderWebOfflinePage()

function inlineScripts(page: string): string[] {
  return [...page.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => m[1])
}

describe('native out/offline.html is byte-identical after the web target (#1674)', () => {
  // Hashes of the renderer's output at 2aecefc, before the web target existed.
  // A change here means the shell's offline page changed: that is a native
  // re-submission concern, not a web one — fix the renderer, not the hash.
  it.each([
    ['prod', () => renderOfflinePage(PROD_SERVER_URL), 'e19db842bcc3a8e9b63800e900dbe1243195566813f2c38e1acec350847d6f02'],
    ['prod + Android hint', () => renderOfflinePage(PROD_SERVER_URL, { androidOfflineHint: true }), '5392fcf15ae9e2dadd775215c6bbea2209cec4d9ff5fb80b3f09b6c9b71ff3ef'],
    ['CAP_SERVER_URL override', () => renderOfflinePage('http://localhost:3000'), '006113b8d8dacb4be01bcb3aabcc0bb4f7115730f1f5a58b4387e8cf47a6f335'],
  ])('%s', (_name, render, expected) => {
    expect(hex(render())).toBe(expected)
  })

  it('target: native is the default', () => {
    expect(renderOfflinePage(PROD_SERVER_URL, { target: 'native' })).toBe(renderOfflinePage(PROD_SERVER_URL))
  })
})

describe('web offline page — self-contained and quiet (#1674)', () => {
  it('loads nothing: no <script src>, no <link>, no absolute URL', () => {
    expect(html).not.toMatch(/<script[^>]*\bsrc=/i)
    expect(html).not.toMatch(/<link\b/i)
    expect(html).not.toMatch(/https?:\/\//)
    expect(html).not.toContain(PROD_SERVER_URL)
  })

  it('has all four locales, from nativeOfflinePage', () => {
    for (const [locale, t] of [['zh-TW', zhTW], ['zh-CN', zhCN], ['en', en], ['ja', ja]] as const) {
      expect(html).toContain(`data-l="${locale}">${t.nativeOfflinePage.title}<`)
      expect(html).toContain(`data-l="${locale}">${t.nativeOfflinePage.offlineBrowsingHint}<`)
    }
  })

  it('has no exclamation marks in any visible copy', () => {
    const copy = [...html.matchAll(/data-l="[^"]+">([^<]*)</g)].map((m) => m[1])
    expect(copy.length).toBeGreaterThanOrEqual(4 * 6)
    for (const text of copy) expect(text).not.toMatch(/[!！]/)
  })

  it('retry is a button that reloads; no link to anywhere', () => {
    expect(html).toContain('<button class="retry" id="retry" type="button">')
    expect(html).not.toMatch(/<a\b/)
  })

  it('reads no location field; only calls location.reload()', () => {
    const uses = html.match(/location\.[A-Za-z]+/g) ?? []
    expect(uses.length).toBeGreaterThan(0)
    expect(new Set(uses)).toEqual(new Set(['location.reload']))
    expect(html).not.toMatch(/document\.(URL|referrer|location)/)
    expect(html).not.toMatch(/window\.location/)
  })

  it('writes no text from data: no innerHTML / textContent / document.write', () => {
    // All copy is baked in; the scripts only toggle <html> attributes and the title.
    expect(html).not.toMatch(/innerHTML|outerHTML|insertAdjacentHTML|document\.write|textContent\s*=/)
  })

  it('probes same-origin /api/ping and counts only 204 && !redirected', () => {
    expect(WEB_PROBE_PATH).toBe('/api/ping')
    const controller = inlineScripts(html)[1]
    expect(controller).toContain('var PROBE_URL = "/api/ping";')
    expect(controller).toContain('res.status !== 204 || res.redirected')
    expect(controller).toContain("cache: 'no-store'")
    expect(controller).not.toContain('no-cors')
  })

  it('locale: the lang cookie against the 4-locale whitelist, then navigator.languages', () => {
    expect(WEB_LOCALE_COOKIE).toBe(LOCALE_COOKIE)
    const head = inlineScripts(html)[0]
    expect(head).toContain('/(?:^|;\\s*)lang=([^;]*)/.exec(document.cookie')
    expect(head).toContain('TITLES.hasOwnProperty(c)')
    expect(head.indexOf('document.cookie')).toBeLessThan(head.indexOf('for (var i = 0; i < tags.length'))
    const titles = JSON.parse(/var TITLES = (\{.*?\});/.exec(head)![1]) as Record<string, string>
    expect(Object.keys(titles).sort()).toEqual([...SUPPORTED_LOCALES].sort())
  })

  it('hint shows only with service worker support and the pref not on', () => {
    expect(WEB_OFFLINE_PREF_KEY).toBe(OFFLINE_PREF_KEY)
    expect(html).toContain('html[data-hint="1"] .hint { display: block; }')
    expect(html).toContain(
      `if ('serviceWorker' in navigator && localStorage.getItem(PREF_KEY) !== 'true') doc.setAttribute('data-hint', '1');`,
    )
  })
})

describe('web offline page — the scripts run as written (#1674)', () => {
  function runHead(cookie: string, languages: string[]) {
    const docEl = { lang: 'zh-TW' }
    const doc = { cookie, documentElement: docEl, title: '' }
    new Function('document', 'navigator', inlineScripts(html)[0])(doc, { languages, language: languages[0] })
    return docEl.lang
  }

  it.each([
    ['lang=ja', ['en-US'], 'ja'],
    ['a=1; lang=zh-CN; b=2', ['ja'], 'zh-CN'],
    ['lang=fr', ['en-GB'], 'en'],
    ['lang=hasOwnProperty', ['ja-JP'], 'ja'],
    ['lang=%3Cscript', [], 'zh-TW'],
    ['', ['zh-HK'], 'zh-TW'],
  ])('cookie %j, languages %j → %s', (cookie, langs, expected) => {
    expect(runHead(cookie, langs)).toBe(expected)
  })
})

describe('generator: page hash → worker bytes and cache name (#1674)', () => {
  it('embeds the page hash in the worker and its cache name', () => {
    const b = buildOfflineBasic('basic')
    expect(b.artifact.pageHash).toBe(sha256Hex(b.page))
    expect(b.worker).toContain(`var PAGE_HASH = "${b.artifact.pageHash}";`)
    expect(b.worker).toContain(`var CACHE = "${basicCacheName(b.artifact.pageHash)}";`)
    expect(basicCacheName(b.artifact.pageHash)).toMatch(/^offline-basic-[0-9a-f]{16}$/)
  })

  it('a copy change changes both the worker bytes and the cache name', () => {
    const a = renderBasicWorker({ pageHash: hex('page A'), mode: 'basic', locales: SUPPORTED_LOCALES })
    const b = renderBasicWorker({ pageHash: hex('page B'), mode: 'basic', locales: SUPPORTED_LOCALES })
    expect(a).not.toBe(b)
    expect(basicCacheName(hex('page A'))).not.toBe(basicCacheName(hex('page B')))
  })

  it('mode kill emits the kill worker: no fetch handler, unregisters itself, never navigates', () => {
    const k = buildOfflineBasic('kill')
    expect(k.artifact.mode).toBe('kill')
    expect(k.worker).toContain('self.registration.unregister()')
    expect(k.worker).not.toContain("addEventListener('fetch'")
    expect(k.worker).not.toMatch(/navigate\(|clients\.matchAll|\.reload\(/)
    expect(k.worker).not.toBe(buildOfflineBasic('basic').worker)
  })

  it('the committed mode is basic', () => {
    expect(SW_BASIC_MODE).toBe('basic')
  })

  it('CSP hashes are the hashes of the inline scripts actually in the page', () => {
    const b = buildOfflineBasic('basic')
    const scripts = inlineScripts(b.page)
    expect(scripts).toHaveLength(2)
    expect(b.artifact.scriptHashes).toEqual(
      scripts.map((s) => `sha256-${createHash('sha256').update(s, 'utf8').digest('base64')}`),
    )
    expect(inlineScriptHashes(b.page)).toEqual(b.artifact.scriptHashes)
    const csp = offlineBasicCsp(b.artifact.scriptHashes)
    for (const h of b.artifact.scriptHashes) expect(csp).toContain(`'${h}'`)
  })

  it('package.json runs the generator as prebuild; outputs are gitignored', () => {
    const pkg = JSON.parse(readFileSync(resolve(repoRoot, 'package.json'), 'utf8')) as { scripts: Record<string, string> }
    expect(pkg.scripts.prebuild).toBe('npm run web:offline-basic')
    expect(pkg.scripts['web:offline-basic']).toContain('scripts/build-web-offline-basic.ts')
    const gitignore = readFileSync(resolve(repoRoot, '.gitignore'), 'utf8').split('\n')
    for (const f of ['/public/sw-basic.js', '/public/offline-basic.html', `/${OFFLINE_BASIC_BUILD_ARTIFACT}`]) {
      expect(gitignore).toContain(f)
    }
  })
})
